ALTER TABLE apple_orders ADD COLUMN tracking_no VARCHAR(20) NULL DEFAULT NULL AFTER shipped_at;
CREATE TABLE IF NOT EXISTS apple_shipping_alimtalk_logs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,tracking_no VARCHAR(20) NOT NULL,success TINYINT(1) NOT NULL DEFAULT 0,http_code INT NOT NULL DEFAULT 0,result_json TEXT NULL,created_at DATETIME NOT NULL,INDEX(order_id),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
